SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(p.entry_reason, 'Execution Intelligence [', -1), ']', 1) AS route, CASE WHEN s.risk_reward_ratio < 1 THEN 'rr_lt1' ELSE 'rr_ge1' END AS rr_bucket, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS gross_pnl FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY route, rr_bucket ORDER BY route, rr_bucket LIMIT 60